    function renderMainPage(data) { const page = document.createElement('div'); page.id = 'page-main'; page.className = 'rotom-page active'; const trainer = data.trainer_info || {}; const tasks = data.tasks || {}; page.innerHTML = `<div class="main-grid"><div class="info-block"><h3>训练家信息</h3><div class="info-item"><span>姓名:</span><span>${trainer.name || 'N/A'}</span></div><div class="info-item"><span>金钱:</span><span>₽${trainer.money || 0}</span></div><div class="info-item"><span>徽章:</span><span>${trainer.badges || 0}</span></div><div class="info-item"><span>命令等级:</span><span>${trainer.command_level || 0}</span></div><div class="info-item"><span>声望:</span><span>${trainer.renown || 'N/A'}</span></div><div class="info-item"><span>称号:</span><span>${trainer.current_title || '无'}</span></div></div><div class="info-block"><h3>冒险记录</h3><div class="info-item"><span>图鉴:</span><span>${trainer.pokedex_caught || 0}/${trainer.pokedex_seen || 0}</span></div><div class="info-item"><span>闪光:</span><span>${trainer.shiny_caught || 0}/${trainer.shiny_seen || 0}</span></div><div class="info-item"><span>传说:</span><span>${trainer.legend_caught || 0}/${trainer.legend_seen || 0}</span></div><div class="info-item"><span>开拓点数:</span><span>${trainer.pioneer_points || 0}</span></div><div class="info-item"><span>成就点数:</span><span>${trainer.achievement_points || 0}</span></div></div><div class="task-block" style="grid-column: 1 / -1;"><h3>任务追踪</h3><div class="task-item"><span>史诗征途:</span><span>${tasks.main || '无'}</span></div><div class="task-item"><span>传说任务:</span><span>${tasks.legend || '无'}</span></div><div class="task-item"><span>每日悬赏:</span><span>${tasks.daily_1 !== '无' ? tasks.daily_1 : (tasks.daily_2 !== '无' ? tasks.daily_2 : '无')}</span></div><div class="task-item"><span>陌生的请求:</span><span>${tasks.random_1 !== '无' ? tasks.random_1 : '无'}</span></div></div></div><div class="main-actions"><button class="rotom-button" data-page="page-nearby">附近宝可梦</button><button class="rotom-button" data-page="page-box">宝可梦盒子</button><button class="rotom-button" data-page="page-team">当前队伍</button><button class="rotom-button" data-page="page-shop">系统商城</button><button class="rotom-button" data-page="page-titles">已拥有称号</button><button class="rotom-button" data-page="page-bag">背包</button><button class="rotom-button" data-page="page-achievements">已解锁成就</button><button class="rotom-button" data-page="page-breeding">繁育盒子</button><button class="rotom-button" data-page="page-relationships">人际关系</button><button class="rotom-button" data-page="page-events">当前大事件</button></div>`; screen.appendChild(page); page.querySelectorAll('.rotom-button[data-page]').forEach(btn => { btn.onclick = () => showPage(btn.dataset.page); }); }
    function renderGenericListPage(id, title, items, itemRenderer) { const page = document.createElement('div'); page.id = id; page.className = 'rotom-page'; const pageTitle = document.createElement('div'); pageTitle.className = 'page-title'; pageTitle.innerHTML = title; page.appendChild(pageTitle); const list = document.createElement('ul'); list.className = 'generic-list'; if (items && Object.keys(items).length > 0) { Object.values(items).forEach(item => { if(item.name && item.name !== '无') list.appendChild(itemRenderer(item)); }); } if (list.children.length === 0) { list.innerHTML = `<li class="generic-list-item">空空如也...</li>`; } page.appendChild(list); page.appendChild(createBackButton('page-main')); screen.appendChild(page); }
    function renderEventsPage(eventsData) { const page = document.createElement('div'); page.id = 'page-events'; page.className = 'rotom-page'; const events = eventsData || {}; page.innerHTML = `<div class="page-title">当前大事件</div><div class="task-block"><h3>周边特殊遭遇</h3><p>${events.local_encounter || '风平浪静，没有特别的宝可梦动向。'}</p></div><div class="task-block"><h3>地区新闻</h3><p>${events.regional_news || '地区内暂无重大新闻。'}</p></div><div class="task-block"><h3>地域动态</h3><p>${events.area_news || '当前区域一片祥和。'}</p></div>`; page.appendChild(createBackButton('page-main')); screen.appendChild(page); }

    function renderPokemonDetailsPage(pokemonKey, pokemon) {
        const uniqueId = `page-details-${pokemonKey}`;
        if(document.getElementById(uniqueId)) { showPage(uniqueId); return; }

        const [currentEXP, totalEXP] = (pokemon.exp || '0/100').split('/').map(Number);
        const expPercent = totalEXP > 0 ? (currentEXP / totalEXP) * 100 : 0;
        const displayName = (pokemon.nickname && pokemon.nickname !== '无') ? pokemon.nickname : pokemon.name;
        let titlePrefix = '';
        if (pokemon.is_shiny === 'true') titlePrefix += '闪光 ';
        if (pokemon.status && pokemon.status !== '无') titlePrefix += `${pokemon.status} `;

        const page = document.createElement('div');
        page.id = uniqueId;
        page.className = 'rotom-page pokemon-details';

        const movesHTML = pokemon.moves.split(',').map(moveStr => {
            const parts = moveStr.split(':'); // 格式: 中文名:属性:分类
            if (parts.length < 3) return `<div class="move-display"><span>${moveStr}</span></div>`;
            const [name, type, category] = parts;
            const typeIcon = `https://raw.githubusercontent.com/msikma/pokesprite/master/misc/types/gen8/${type.toLowerCase()}.png`;
            const categoryMap = {'物理': 'physical', '特殊': 'special', '变化': 'status'};
            const categoryIcon = `https://raw.githubusercontent.com/msikma/pokesprite/master/misc/seals/gen8/move-${categoryMap[category] || 'status'}.png`;
            return `<div class="move-display">
                        <img src="${typeIcon}" class="type-icon" title="${type}">
                        <img src="${categoryIcon}" class="move-icon" title="${category}">
                        <span>${name}</span>
                    </div>`;
        }).join('');

        page.innerHTML = `
            <div class="pokemon-sprite-container">
                <img src="${getPokemonImageUrl(pokemon)}" class="main-sprite">
                <div class="status-icons">${getStatusIcons(pokemon)}</div>
            </div>
            <div class="page-title">${titlePrefix}${displayName} <span>(Lv.${pokemon.level})</span></div>
            <div class="tabs"><button class="tab-button active" data-tab="info">基本信息</button><button class="tab-button" data-tab="stats">能力</button><button class="tab-button" data-tab="potential">潜能</button></div>
            <div id="tab-info-${pokemonKey}" class="tab-content active">
                <div class="pokemon-info-grid">
                    <div><strong>种类:</strong> ${pokemon.name}</div>
                    <div><strong>性别:</strong> ${pokemon.gender}</div>
                    <div><strong>属性:</strong> ${pokemon.types}</div>
                    <div><strong>特性:</strong> ${pokemon.ability}</div>
                    <div><strong>性格:</strong> ${pokemon.nature}</div>
                    <div><strong>亲密度:</strong> ${pokemon.friendship}</div>
                    <div><strong>携带道具:</strong> <img src="${getItemImageUrl({english_name: pokemon.held_item_en})}" class="item-icon">${pokemon.held_item}</div>
                    <div style="grid-column: 1 / -1;"><strong>经验值:</strong> ${pokemon.exp || 'N/A'}<div class="exp-bar-bg"><div class="exp-bar-fg" style="width: ${expPercent}%;"></div></div></div>
                    <div style="grid-column: 1 / -1;"><strong>技能:</strong><div class="moves-list">${movesHTML}</div></div>
                </div>
            </div>
            <div id="tab-stats-${pokemonKey}" class="tab-content"><div class="pokemon-stats-grid"><div><strong>HP:</strong> ${pokemon.hp.split('/')[1]}</div>${pokemon.stats.split(',').map(s => `<div><strong>${s.split(':')[0].toUpperCase()}:</strong> ${s.split(':')[1]}</div>`).join('')}</div></div>
            <div id="tab-potential-${pokemonKey}" class="tab-content"><p><strong>个体值 (IVs):</strong></p><div class="pokemon-info-grid"> ${pokemon.ivs.split(',').map(s => `<div><strong>${s.split(':')[0].toUpperCase()}:</strong> ${s.split(':')[1]}</div>`).join('')}</div></div>`;

        page.appendChild(createBackButton('page-team'));
        screen.appendChild(page);
        page.querySelectorAll('.tab-button').forEach(button => {
            button.addEventListener('click', () => {
                page.querySelectorAll('.tab-button').forEach(btn => btn.classList.remove('active'));
                button.classList.add('active');
                page.querySelectorAll('.tab-content').forEach(content => content.classList.remove('active'));
                page.querySelector(`#tab-${button.dataset.tab}-${pokemonKey}`).classList.add('active');
            });
        });
        showPage(page.id);
    }

    function renderTeamPage(teamData) {
        const page = document.createElement('div');
        page.id = 'page-team';
        page.className = 'rotom-page';
        page.innerHTML = `<div class="page-title">当前队伍</div>`;
        const grid = document.createElement('div');
        grid.className = 'team-grid';
        Object.entries(teamData).forEach(([pokemonKey, pokemon]) => {
            if (pokemon.name && pokemon.name !== '无') {
                const displayName = (pokemon.nickname && pokemon.nickname !== '无') ? pokemon.nickname : pokemon.name;
                let titlePrefix = '';
                if (pokemon.is_shiny === 'true') titlePrefix += '闪光 ';
                if (pokemon.status && pokemon.status !== '无' && pokemon.status.toLowerCase() !== 'normal' ) titlePrefix += `${pokemon.status} `;

                const memberDiv = document.createElement('div');
                memberDiv.className = 'team-member';
                memberDiv.innerHTML = `<img src="${getPokemonImageUrl(pokemon)}" class="pokemon-icon"> <span>${titlePrefix}${displayName} (Lv.${pokemon.level})</span>`;
                memberDiv.onclick = () => renderPokemonDetailsPage(pokemonKey, pokemon);
                grid.appendChild(memberDiv);
            }
        });
        page.appendChild(grid);
        page.appendChild(createBackButton('page-main'));
        screen.appendChild(page);
    }

    function renderShopPage(shopData, pp) { renderGenericListPage('page-shop', `开拓者交易所 <span class="currency">${pp || 0} PP</span>`, shopData || {}, item => { const li = document.createElement('li'); li.className = 'generic-list-item'; li.innerHTML = `<div class="generic-list-item-content"><img src="${getItemImageUrl(item)}" class="item-icon"><strong>${item.name}</strong></div><div class="item-actions"><span class="item-cost">${item.cost} PP</span><button class="item-button">购买</button></div>`; const buyButton = li.querySelector('.item-button'); buyButton.onclick = async () => { if ((parseInt(pp, 10) || 0) < (parseInt(item.cost, 10) || 0)) { showError(`哔哔！点数不足！ (需要 ${item.cost} PP)`); return; } buyButton.disabled = true; buyButton.textContent = '发送中...'; const success = await sendGameActionRequest(`/send 花费${item.cost}PP 购买了 ${item.name}`); buyButton.textContent = success ? '已发送 ✓' : '请手动发送'; if (success) { setTimeout(() => { buyButton.textContent = '购买'; buyButton.disabled = false; }, 2500); } }; return li; }); }
    function renderTitlesPage(titlesData, currentTitle) { renderGenericListPage('page-titles', '已拥有称号', titlesData || {}, item => { const li = document.createElement('li'); const isEquipped = item.name === currentTitle; li.className = 'generic-list-item'; li.innerHTML = `<div class="generic-list-item-content"><div><strong>${item.name} ${isEquipped ? `<span style=\"color: var(--accent-red);\'>(已装备)</span>` : ''}</strong><small style="display: block; opacity: 0.8;">${item.effect}</small></div></div><div class="item-actions">${!isEquipped ? '<button class="equip-button">装备</button>' : ''}</div>`; if (!isEquipped) { const equipButton = li.querySelector('.equip-button'); equipButton.onclick = async () => { equipButton.disabled = true; equipButton.textContent = '发送中...'; const success = await sendGameActionRequest(`/send 切换称号为 ${item.name}`); equipButton.textContent = success ? '已发送 ✓' : '请手动发送'; }; } return li; }); }
    function renderBreedingPage(data) { const page = document.createElement('div'); page.id = 'page-breeding'; page.className = 'rotom-page'; let content = (data && (data.status === '进行中' || data.status === '已完成')) ? `<h3>状态: ${data.status}</h3><div class="generic-list-item">宝可梦 A: ${data.pokemon_A}</div><div class="generic-list-item">宝可梦 B: ${data.pokemon_B}</div>` : `<div class="generic-list-item">没有宝可梦在培育屋。</div>`; page.innerHTML = `<div class="page-title">繁育盒子</div>${content}`; page.appendChild(createBackButton('page-main')); screen.appendChild(page); }

    // Initial Render
    const rawData = (dataContainer.value || dataContainer.textContent || '').trim();
    if (rawData) {
        try {
            const data = parseRotomData(rawData);
            screen.innerHTML = '';
            renderMainPage(data);
            renderGenericListPage('page-nearby', '附近宝可梦', data.nearby_pokemon, item => { const li = document.createElement('li'); li.className = 'generic-list-item'; li.innerHTML = `<div class="generic-list-item-content"><img src="${getPokemonImageUrl(item)}" class="pokemon-icon"><span><strong>${item.name}</strong></span></div><span>${item.count}</span>`; return li; });
            renderGenericListPage('page-box', '宝可梦盒子', data.pokemon_box, item => { const li = document.createElement('li'); li.className = 'generic-list-item'; li.innerHTML = `<div class="generic-list-item-content"><img src="${getPokemonImageUrl(item)}" class="pokemon-icon"><span><strong>${item.name}</strong></span></div><span>Lv.${item.level}</span>`; return li; });
            renderTeamPage(data.current_team || {});
            renderShopPage(data.system_shop, (data.trainer_info || {}).pioneer_points);
            renderTitlesPage(data.unlocked_titles, (data.trainer_info || {}).current_title);
            renderGenericListPage('page-bag', '背包', data.bag, item => { const li = document.createElement('li'); li.className = 'generic-list-item'; li.innerHTML = `<div class="generic-list-item-content"><img src="${getItemImageUrl(item)}" class="item-icon"><span><strong>${item.name}</strong></span></div><span>x${item.count}</span>`; return li; });
            renderGenericListPage('page-achievements', `已解锁成就 (${(data.trainer_info || {}).achievement_points || 0} AP)`, data.unlocked_achievements, item => { const li = document.createElement('li'); li.className = 'generic-list-item'; li.innerHTML = `<div class="generic-list-item-content"><div><strong>${item.name}</strong><small style="display:block; opacity:0.8;">${item.desc}</small></div></div>`; return li; });
            renderBreedingPage(data.breeding_box || {});
            renderGenericListPage('page-relationships', '人际关系', data.relationships, item => { const li = document.createElement('li'); li.className = 'generic-list-item'; li.innerHTML = `<span><strong>${item.name}</strong></span><span>好感度: ${item.favorability}</span>`; return li; });
            renderEventsPage(data.world_events);
        } catch (e) {
            console.error("Rotom Dex failed to initialize:", e);
            screen.innerHTML = `<div class="page-title" style='color:red;'>数据错误</div><p>洛托姆数据传输中断...滋滋...<br>请检查你的输入格式是否正确！<br><br>错误详情: ${e.message}</p>`;
            const mainPage = document.createElement('div'); mainPage.id = 'page-main'; mainPage.className = 'rotom-page active'; mainPage.innerHTML = screen.innerHTML; screen.innerHTML = ''; screen.appendChild(mainPage);
        }
    } else {
        screen.innerHTML = '<p>洛托姆数据传输中断...滋滋...</p>';
    }
});
